AUTH_VARIABLE_INDEX = '\nFile: auth.info,  Node: Variable Index,  Prev: Function Index,  Up: Top\n\nVariable Index\n**************\n\n\x00\x08[index\x00\x08]\n* Menu:\n\n* auth-source-debug:                     Help for developers.  (line  8)\n* auth-source-pass-extra-query-keywords: The Unix password store.\n                                                               (line 74)\n* auth-source-pass-filename:             The Unix password store.\n                                                               (line 66)\n* auth-source-pass-port-separator:       The Unix password store.\n                                                               (line 70)\n* auth-sources:                          Help for users.       (line 74)\n* secrets-enabled:                       Secret Service API.   (line 17)\n\n\n'




def _write_gz(path: Path, text: str) -> None:
    with gzip.open(path, "wt", encoding="utf-8") as fh:
        fh.write(text)


def test_drops_preamble_header_and_tag_table():
    """Preamble, node headers, and the Tag Table / End Tag Table / Local
    Variables trailer are all dropped; only the node bodies remain."""
    text = "\x1f".join(
        [PREAMBLE, VISITING, OTHER_INPUT, AUTH_TAG_TABLE, AUTH_END_TAG_TABLE, AUTH_LOCAL_VARS]
    )
    nodes = list(extract_info.iter_nodes(text))
    names = [n for n, _ in nodes]
    assert names == ["Visiting", "Other Input"], names
    for name, body in nodes:
        assert not body.lstrip("\n").startswith("File:"), (name, body[:60])
        assert "Tag Table" not in body
        assert "Local Variables" not in body


def test_skip_index_nodes():
    """Real index nodes (auth.info.gz's Index, Function Index, Variable
    Index) are skipped; a real non-index node in the same manual is kept."""
    text = "\x1f".join(
        [PREAMBLE, VISITING, AUTH_INDEX, AUTH_FUNCTION_INDEX, AUTH_VARIABLE_INDEX]
    )
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        indir = tmp / "in"
        indir.mkdir()
        _write_gz(indir / "demo.info.gz", text)
        md_text, kept, skipped = extract_info.convert_manual(indir / "demo.info.gz")
    assert kept == 1, kept
    assert skipped == 3, skipped
    assert "## Visiting" in md_text
    assert "Index" not in [ln[3:] for ln in md_text.splitlines() if ln.startswith("## ")]


def _node_body(seg_text: str) -> str:
    """Drop the `File: ...  Node: ...` header line the way iter_nodes does."""
    return seg_text.lstrip("\n").split("\n", 1)[1]


def test_menu_stripped_and_prose_kept_after_menu():
    """The Texinfo `* Menu:` table of contents is always dropped; real prose
    that happens to follow one (a footnote block, an ordinary paragraph) is
    always kept. Four real shapes, from four different manuals."""
    # emacs.info Top: intro prose kept; entries, group labels, and the
    # "-- The Detailed Node Listing --" divider are all part of the menu and
    # are dropped.
    top_body = extract_info.strip_menu(_node_body(EMACS_TOP))
    assert "* Menu:" not in top_body
    assert "Distrib::" not in top_body
    assert "Important General Concepts" not in top_body
    assert "The Detailed Node Listing" not in top_body
    assert "Emacs is the advanced, extensible, customizable" in top_body

    # org.info Top: same shape, different manual.
    org_body = extract_info.strip_menu(_node_body(ORG_TOP))
    assert "* Menu:" not in org_body
    assert "Introduction::" not in org_body
    assert "This manual is for Org version 9.5." in org_body

    # emacs.info Other Input: a menu with nothing real after it - body is
    # whatever came before "* Menu:" (here, just the title), once stripped.
    other_body = extract_info.strip_menu(_node_body(OTHER_INPUT))
    assert "* Menu:" not in other_body
    assert "Touchscreens::" not in other_body

    # ccmode.info Config Basics: menu, then a real Footnotes block - kept.
    # (the body's prose legitimately contains "*note CC Hooks::", an inline
    # cross-reference, not a menu entry - only the real "\n* CC Hooks::"
    # menu-entry line should be gone.)
    cc_body = extract_info.strip_menu(_node_body(CCMODE_CONFIG_BASICS))
    assert "* Menu:" not in cc_body
    assert "\n* CC Hooks::" not in cc_body
    assert "*note CC Hooks::" in cc_body
    assert "Footnotes" in cc_body
    assert "DON'T PANIC" in cc_body

    # elisp.info Autoload node: menu, then an ordinary prose paragraph - kept.
    # (the kept prose legitimately references "*note Autoload by Prefix::",
    # an inline cross-reference, not a menu entry.)
    elisp_body = extract_info.strip_menu(_node_body(ELISP_AUTOLOAD))
    assert "* Menu:" not in elisp_body
    assert "\n* Autoload by Prefix::" not in elisp_body
    assert "There are two ways to set up an autoloaded function" in elisp_body


def test_neutralises_markdown_heading_lines():
    """A body line matching ^#{1,6}\\s (calc.info.gz's one real instance) is
    indented by one space so ingest.py's markdown-heading regex misses it;
    ordinary lines, including a bare "#" with no following whitespace, are
    left untouched."""
    neutralised = extract_info.neutralise_headings(CALC_EXCERPT)
    assert not re.search(r"^#{1,6}\s", neutralised, re.M)
    assert "rule, since an expression in parentheses" in neutralised

    assert extract_info.neutralise_headings("### three\n") == " ### three\n"
    assert extract_info.neutralise_headings("#no-space\n") == "#no-space\n"
    assert extract_info.neutralise_headings("plain text\n") == "plain text\n"


def test_disambiguates_slug_collision():
    """info.info.gz's real "Help" / "Help-]" collision (both slug to "help")
    is resolved deterministically; every other real Help-* name is untouched."""
    out = extract_info.disambiguate(HELP_NAMES)
    slugs = [slug(n) for n in out]
    assert len(slugs) == len(set(slugs)), slugs
    assert out[HELP_NAMES.index("Help")] == "Help"
    assert out[HELP_NAMES.index("Help-]")] == "Help-] (2)"
    untouched = [n for n in HELP_NAMES if n not in ("Help", "Help-]")]
    for n in untouched:
        assert n in out


def test_end_to_end_cli_produces_expected_sec_ids():
    """A real tiny manual, converted by the actual CLI, feeds through
    smm.ingest.from_file to the exact sec_ids the two kept real nodes
    (Visiting, Other Input) should produce - Index nodes contribute none."""
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        indir = tmp / "in"
        outdir = tmp / "out"
        indir.mkdir()
        text = "\x1f".join(
            [PREAMBLE, VISITING, OTHER_INPUT, AUTH_INDEX,
             AUTH_TAG_TABLE, AUTH_END_TAG_TABLE, AUTH_LOCAL_VARS]
        )
        _write_gz(indir / "demo.info.gz", text)

        result = subprocess.run(
            [sys.executable, str(ROOT / "scripts" / "extract_info.py"),
             str(indir), "--out", str(outdir)],
            capture_output=True, text=True, check=True,
        )
        assert "1 files" in result.stdout, result.stdout
        assert "2 nodes" in result.stdout, result.stdout
        assert "1 index nodes skipped" in result.stdout, result.stdout

        outfile = outdir / "demo.md"
        assert outfile.exists()
        doc = from_file(outfile, "testdomain")
        sec_ids = [s["sec_id"] for s in doc["sections"]]
        expected = {
            f"demo.testdomain#{slug('Visiting')}",
            f"demo.testdomain#{slug('Other Input')}",
        }
        assert set(sec_ids) == expected, sec_ids
        assert len(sec_ids) == len(set(sec_ids)) == 2
        assert doc["sections"][0]["heading"] != "Introduction"


def test_nothing_before_first_heading():
    """No preamble/title text is ever written before the first "## " line,
    so ingest.py's `_sections_from_markdown` never invents an extra
    "Introduction" section for a converted manual."""
    with tempfile.TemporaryDirectory() as tmp:
        tmp = Path(tmp)
        indir = tmp / "in"
        outdir = tmp / "out"
        indir.mkdir()
        text = "\x1f".join([PREAMBLE, VISITING, OTHER_INPUT])
        _write_gz(indir / "demo.info.gz", text)
        extract_info.main([str(indir), "--out", str(outdir)])

        content = (outdir / "demo.md").read_text(encoding="utf-8")
        assert content.startswith("## Visiting\n\n"), content[:40]

        doc = from_file(outdir / "demo.md", "testdomain")
        headings = [s["heading"] for s in doc["sections"]]
        assert "Introduction" not in headings, headings


